exports.buildPeerTopologyMermaid = buildPeerTopologyMermaid;
/** Build Mermaid LR graph for peer topology (connected links only). */
function buildPeerTopologyMermaid(topology, peers, connections) {
    const safe = (id) => id.replace(/-/g, "_");
    let mermaid = `graph LR\n  topology[${topology}]\n`;
    peers.forEach((p) => {
        mermaid += `  ${safe(p)}[${p}]\n`;
    });
    connections
        .filter((c) => c.connected)
        .forEach((c) => {
        mermaid += `  ${safe(c.fromPeerId)} --> ${safe(c.toPeerId)}\n`;
    });
    return mermaid;
}
